import { hasWorkspaceAccess,workspaceAccessResponse,workspaceContext,workspaceModuleAccessResponse } from '../../../contractor-auth';
import { vendorCategories,type VendorCategory } from '../../../vendor-manager';
const clean=(value:unknown,max=500)=>String(value||'').trim().slice(0,max),stamp=()=>new Date().toISOString();
function category(value:unknown):VendorCategory|null{const candidate=clean(value,40) as VendorCategory;return vendorCategories.includes(candidate)?candidate:null}
export async function GET(){const context=await workspaceContext();if(!hasWorkspaceAccess(context))return workspaceAccessResponse(context)!;const denied=workspaceModuleAccessResponse(context,'job-management');if(denied)return denied;const [vendors,jobs,workflows,closeouts,jobAssignments,workflowAssignments,closeoutReferences]=await context.db.batch([
  context.db.prepare('SELECT * FROM vendors WHERE workspace_id=? ORDER BY preferred DESC,name COLLATE NOCASE').bind(context.workspaceId),
  context.db.prepare("SELECT id,name,project_type_key,project_type_category,smart_defaults_json FROM projects WHERE workspace_id=? AND status='active' ORDER BY updated_at DESC").bind(context.workspaceId),
  context.db.prepare("SELECT i.id,i.project_id,i.template_key,p.name project_name FROM workflow_instances i JOIN projects p ON p.id=i.project_id AND p.workspace_id=i.workspace_id WHERE i.workspace_id=? AND i.status<>'archived' ORDER BY i.updated_at DESC").bind(context.workspaceId),
  context.db.prepare("SELECT g.id,g.project_id,p.name project_name,g.status FROM closeout_task_groups g JOIN projects p ON p.id=g.project_id AND p.workspace_id=g.workspace_id WHERE g.workspace_id=? ORDER BY g.updated_at DESC").bind(context.workspaceId),
  context.db.prepare('SELECT a.*,v.name vendor_name,v.category FROM job_vendor_assignments a JOIN vendors v ON v.id=a.vendor_id AND v.workspace_id=a.workspace_id WHERE a.workspace_id=? ORDER BY a.created_at DESC').bind(context.workspaceId),
  context.db.prepare('SELECT a.*,v.name vendor_name,v.category FROM workflow_vendor_assignments a JOIN vendors v ON v.id=a.vendor_id AND v.workspace_id=a.workspace_id WHERE a.workspace_id=? ORDER BY a.created_at DESC').bind(context.workspaceId),
  context.db.prepare('SELECT a.*,v.name vendor_name,v.category FROM closeout_vendor_references a JOIN vendors v ON v.id=a.vendor_id AND v.workspace_id=a.workspace_id WHERE a.workspace_id=? ORDER BY a.created_at DESC').bind(context.workspaceId),
]);return Response.json({vendors:vendors.results,jobs:jobs.results,workflows:workflows.results,closeouts:closeouts.results,jobAssignments:jobAssignments.results,workflowAssignments:workflowAssignments.results,closeoutReferences:closeoutReferences.results,categories:vendorCategories,trialDaysRemaining:context.trialDaysRemaining})}

export async function POST(request:Request){const context=await workspaceContext();if(!hasWorkspaceAccess(context))return workspaceAccessResponse(context)!;const denied=workspaceModuleAccessResponse(context,'job-management');if(denied)return denied;let body:Record<string,unknown>;try{body=await request.json() as Record<string,unknown>}catch{return Response.json({error:'Invalid request'},{status:400})}const action=clean(body.action,40);
  if(action==='create'||action==='update'){const name=clean(body.name,180),vendorCategory=category(body.category);if(!name||!vendorCategory)return Response.json({error:'Vendor name and a valid category are required.'},{status:400});const id=action==='create'?crypto.randomUUID():clean(body.id,100),now=stamp(),values=[name,vendorCategory,body.preferred?1:0,clean(body.contactName,160),clean(body.email,254).toLowerCase(),clean(body.phone,80),clean(body.website,500),clean(body.address,500),clean(body.notes,3000),now];if(action==='create'){await context.db.prepare('INSERT INTO vendors (id,workspace_id,name,category,preferred,contact_name,email,phone,website,address,notes,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id,context.workspaceId,...values.slice(0,9),context.user.id,now,now).run()}else{const result=await context.db.prepare('UPDATE vendors SET name=?,category=?,preferred=?,contact_name=?,email=?,phone=?,website=?,address=?,notes=?,updated_at=? WHERE id=? AND workspace_id=?').bind(...values,id,context.workspaceId).run();if(!result.meta.changes)return Response.json({error:'Vendor not found.'},{status:404})}return Response.json({ok:true,id})}
  if(action==='delete'){const id=clean(body.id,100);const result=await context.db.prepare('DELETE FROM vendors WHERE id=? AND workspace_id=?').bind(id,context.workspaceId).run();return result.meta.changes?Response.json({ok:true}):Response.json({error:'Vendor not found.'},{status:404})}
  if(action==='assign'||action==='unassign'){const targetType=clean(body.targetType,30),targetId=clean(body.targetId,100),vendorId=clean(body.vendorId,100),note=clean(body.note,500);const vendor=await context.db.prepare('SELECT id FROM vendors WHERE id=? AND workspace_id=?').bind(vendorId,context.workspaceId).first();if(!vendor)return Response.json({error:'Vendor not found in this company workspace.'},{status:404});let table='',column='';if(targetType==='job'){table='job_vendor_assignments';column='project_id'}else if(targetType==='workflow'){table='workflow_vendor_assignments';column='workflow_instance_id'}else if(targetType==='closeout'){table='closeout_vendor_references';column='closeout_task_group_id'}else return Response.json({error:'Choose a valid assignment destination.'},{status:400});const targetSql=targetType==='job'?"SELECT id FROM projects WHERE id=? AND workspace_id=? AND status='active'":targetType==='workflow'?"SELECT id FROM workflow_instances WHERE id=? AND workspace_id=? AND status<>'archived'":"SELECT id FROM closeout_task_groups WHERE id=? AND workspace_id=?";const target=await context.db.prepare(targetSql).bind(targetId,context.workspaceId).first();if(!target)return Response.json({error:'Assignment destination not found in this company workspace.'},{status:404});if(action==='unassign'){await context.db.prepare(`DELETE FROM ${table} WHERE workspace_id=? AND ${column}=? AND vendor_id=?`).bind(context.workspaceId,targetId,vendorId).run();return Response.json({ok:true})}const textColumn=targetType==='closeout'?'reference_note':'assignment_role';await context.db.prepare(`INSERT OR REPLACE INTO ${table} (id,workspace_id,${column},vendor_id,${textColumn},created_by,created_at) VALUES (?,?,?,?,?,?,?)`).bind(crypto.randomUUID(),context.workspaceId,targetId,vendorId,note,context.user.id,stamp()).run();return Response.json({ok:true})}
  return Response.json({error:'Unknown Vendor Manager action.'},{status:400});
}
